'use client';

/**
 * SHEHSWAR ONE360 - Unified All Products & Items Master (Zero-Rate / Master Only)
 *
 * Dedicated strictly to defining and maintaining the identity and specifications of products/items:
 * - Product Code (Auto-generated by backend)
 * - Product Name (with optional Urdu designation)
 * - Product Type (Finished Product, Raw Material, Packing Material, Other Item)
 * - Category (with auto-generated code and inline creation)
 * - Pack Size (dynamic commercial specification, e.g. 25 KG, 2 L, 500 ML)
 * - Unit of Measure (UoM with inline creation)
 * - Status (Active / Inactive)
 *
 * Architectural Segregation Mandate:
 * - Zero pricing, rate, discount, net rate, or scheme fields in the Product Master.
 * - Procurement rates belong to Purchase Orders / GRN.
 * - Manufacturing costs belong to the Costing Engine.
 * - Selling rates belong to Rate Lists and Schemes.
 */
import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { ApiClient } from '../../lib/api-client';
import { useToast } from '../../context/toast-context';
import { ListPageTemplate } from '../templates';
import {
  Card,
  Button,
  Input,
  Select,
  DataTable,
  KpiCard,
  StatusBadge,
  TableSkeleton,
  EmptyState,
  ErrorState,
  Modal,
} from '../ui';
import {
  IconFlask,
  IconPackage,
  IconPlus,
  IconRefresh,
  IconDownload,
  IconEye,
  IconEdit,
  IconTrash,
  IconTag,
  IconAlertTriangle,
  IconBox,
} from '../icons';
import { ProductImportModal } from './ProductImportModal';
import { AddBatchModal } from '../operations/AddBatchModal';

export type ProductTab = 'ALL' | 'RAW_MATERIAL' | 'PACKING_MATERIAL' | 'FINISHED_PRODUCT' | 'OTHER';

export interface UnifiedProductItem {
  id: string;
  code: string;
  name: string;
  urduName?: string | null;
  itemType: 'RAW_MATERIAL' | 'PACKING_MATERIAL' | 'FINISHED_PRODUCT' | 'OTHER';
  itemTypeLabel: string;
  categoryName: string;
  categoryCode?: string | null;
  categoryId?: string | null;
  baseUomName: string;
  baseUomSymbol?: string | null;
  packSize?: string | null;
  grade?: string | null;
  specifications?: string | null;
  storageRequirements?: string | null;
  isHazardous?: boolean;
  batchesCount?: number;
  status: string;
  isActive: boolean;
  createdAt?: string;
  updatedAt?: string;
  rawRecord: any;
}

export interface AllProductsAndItemsViewProps {
  defaultTab?: ProductTab;
}

export const AllProductsAndItemsView: React.FC<AllProductsAndItemsViewProps> = ({
  defaultTab = 'ALL',
}) => {
  const { showToast } = useToast();

  // Active Category Tab
  const [activeTab, setActiveTab] = useState<ProductTab>(defaultTab);

  // Data State
  const [items, setItems] = useState<UnifiedProductItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Filtering State
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('ALL');
  const [statusFilter, setStatusFilter] = useState('ALL');

  // Master Data Options
  const [categories, setCategories] = useState<any[]>([]);
  const [uoms, setUoms] = useState<any[]>([]);

  // Product Master Modal State (Zero Pricing Fields)
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [editingItemId, setEditingItemId] = useState<string | null>(null);
  const [productForm, setProductForm] = useState({
    itemType: 'FINISHED_PRODUCT' as 'FINISHED_PRODUCT' | 'RAW_MATERIAL' | 'PACKING_MATERIAL' | 'OTHER',
    code: 'AUTO',
    name: '',
    urduName: '',
    categoryId: '',
    packSize: '',
    uomId: '',
    status: 'ACTIVE',
    description: '',
  });
  const [isSavingProduct, setIsSavingProduct] = useState(false);

  // Inline Category Creation Modal State
  const [isInlineCategoryModalOpen, setIsInlineCategoryModalOpen] = useState(false);
  const [inlineCategoryForm, setInlineCategoryForm] = useState({
    name: '',
    description: '',
    type: 'RAW_MATERIAL' as 'RAW_MATERIAL' | 'PACKING_MATERIAL' | 'FINISHED_PRODUCT',
  });
  const [isSavingCategory, setIsSavingCategory] = useState(false);

  // Inline UoM Creation Modal State
  const [isInlineUomModalOpen, setIsInlineUomModalOpen] = useState(false);
  const [inlineUomForm, setInlineUomForm] = useState({
    name: '',
    symbol: '',
    category: 'WEIGHT' as 'WEIGHT' | 'VOLUME' | 'COUNT' | 'LENGTH',
  });
  const [isSavingUom, setIsSavingUom] = useState(false);

  // Modals for Detail View, Delete, Batches, Import
  const [viewingItem, setViewingItem] = useState<UnifiedProductItem | null>(null);
  const [deletingItem, setDeletingItem] = useState<UnifiedProductItem | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [batchModalProduct, setBatchModalProduct] = useState<any | null>(null);
  const [isImportOpen, setIsImportOpen] = useState(false);

  // Update activeTab when defaultTab changes
  useEffect(() => {
    if (defaultTab) {
      setActiveTab(defaultTab);
    }
  }, [defaultTab]);

  // Load All Products Data from Real API
  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const [productsRes, catRes, uomRes] = await Promise.all([
        ApiClient.get<UnifiedProductItem[]>('/api/v1/master-data/all-products?tab=ALL'),
        ApiClient.get<any[]>('/api/v1/master-data/unified-categories').catch(() =>
          ApiClient.get<any[]>('/api/v1/master-data/material-categories')
        ),
        ApiClient.get<any[]>('/api/v1/master-data/uoms'),
      ]);

      setItems(productsRes.data || []);
      setCategories(catRes.data || []);
      setUoms(uomRes.data || []);
    } catch (err: any) {
      setError(err.message || 'Failed to load products and items master');
      showToast({
        title: 'Connection Error',
        message: err.message || 'Could not fetch products catalog',
        type: 'error',
      });
    } finally {
      setIsLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Tab Counts for Badges
  const tabCounts = useMemo(() => {
    return {
      ALL: items.length,
      RAW_MATERIAL: items.filter((i) => i.itemType === 'RAW_MATERIAL').length,
      PACKING_MATERIAL: items.filter((i) => i.itemType === 'PACKING_MATERIAL').length,
      FINISHED_PRODUCT: items.filter((i) => i.itemType === 'FINISHED_PRODUCT').length,
      OTHER: items.filter((i) => i.itemType === 'OTHER').length,
    };
  }, [items]);

  // Filtered Items based on Tab, Search & Dropdown Filters
  const filteredItems = useMemo(() => {
    let result = items;

    // 1. Tab Filter
    if (activeTab === 'RAW_MATERIAL') {
      result = result.filter((i) => i.itemType === 'RAW_MATERIAL');
    } else if (activeTab === 'PACKING_MATERIAL') {
      result = result.filter((i) => i.itemType === 'PACKING_MATERIAL');
    } else if (activeTab === 'FINISHED_PRODUCT') {
      result = result.filter((i) => i.itemType === 'FINISHED_PRODUCT');
    } else if (activeTab === 'OTHER') {
      result = result.filter((i) => i.itemType === 'OTHER');
    }

    // 2. Search Query across Code, Name, Urdu, Category, Type, Pack Size, UOM
    const q = (searchQuery || '').trim().toLowerCase();
    if (q) {
      result = result.filter((i) => {
        return (
          (i.code || '').toLowerCase().includes(q) ||
          (i.name || '').toLowerCase().includes(q) ||
          (i.urduName || '').toLowerCase().includes(q) ||
          (i.itemTypeLabel || '').toLowerCase().includes(q) ||
          (i.categoryName || '').toLowerCase().includes(q) ||
          (i.baseUomName || '').toLowerCase().includes(q) ||
          (i.baseUomSymbol || '').toLowerCase().includes(q) ||
          (i.packSize || '').toLowerCase().includes(q) ||
          (i.grade || '').toLowerCase().includes(q)
        );
      });
    }

    // 3. Category Filter
    if (categoryFilter !== 'ALL') {
      result = result.filter((i) => i.categoryId === categoryFilter || i.categoryName === categoryFilter);
    }

    // 4. Status Filter
    if (statusFilter === 'ACTIVE') {
      result = result.filter((i) => i.isActive);
    } else if (statusFilter === 'INACTIVE') {
      result = result.filter((i) => !i.isActive);
    }

    return result;
  }, [items, activeTab, searchQuery, categoryFilter, statusFilter]);

  // Handle Open Create Product Modal
  const handleOpenCreateModal = (presetType?: 'FINISHED_PRODUCT' | 'RAW_MATERIAL' | 'PACKING_MATERIAL' | 'OTHER') => {
    let initialType: 'FINISHED_PRODUCT' | 'RAW_MATERIAL' | 'PACKING_MATERIAL' | 'OTHER' = 'FINISHED_PRODUCT';
    if (presetType) {
      initialType = presetType;
    } else if (activeTab === 'RAW_MATERIAL') {
      initialType = 'RAW_MATERIAL';
    } else if (activeTab === 'PACKING_MATERIAL') {
      initialType = 'PACKING_MATERIAL';
    } else if (activeTab === 'FINISHED_PRODUCT') {
      initialType = 'FINISHED_PRODUCT';
    } else if (activeTab === 'OTHER') {
      initialType = 'OTHER';
    }

    // Select suitable default category and UoM
    const matchingCat = categories.find((c) =>
      initialType === 'FINISHED_PRODUCT'
        ? c.entityType === 'FINISHED_PRODUCT' || c.categoryType === 'FINISHED_PRODUCT'
        : initialType === 'OTHER'
        ? c.code === '41-87' || (c.name || '').toLowerCase().includes('other') || c.categoryType === 'BOTH'
        : c.entityType === initialType || c.categoryType === initialType
    );

    const defaultUom = uoms.find((u) =>
      initialType === 'FINISHED_PRODUCT'
        ? /liter|ltr|pcs|piece/i.test(u.name || '')
        : initialType === 'PACKING_MATERIAL'
        ? /pcs|piece|nos|bag/i.test(u.name || '')
        : /kg|kilogram|liter|ltr/i.test(u.name || '')
    ) || uoms[0];

    const defaultPack = initialType === 'FINISHED_PRODUCT' ? '1 L' : initialType === 'RAW_MATERIAL' ? '25 KG' : 'PCS';

    setEditingItemId(null);
    setProductForm({
      itemType: initialType,
      code: 'AUTO',
      name: '',
      urduName: '',
      categoryId: matchingCat?.id || categories[0]?.id || '',
      packSize: defaultPack,
      uomId: defaultUom?.id || '',
      status: 'ACTIVE',
      description: '',
    });
    setIsProductModalOpen(true);
  };

  // Handle Edit Item (Prefill master fields only — ZERO pricing)
  const handleEditItem = (item: UnifiedProductItem) => {
    setEditingItemId(item.id);
    const matchedUom = uoms.find(
      (u) =>
        u.name === item.baseUomName ||
        u.symbol === item.baseUomSymbol ||
        u.code === item.baseUomSymbol
    );

    setProductForm({
      itemType: item.itemType,
      code: item.code,
      name: item.name,
      urduName: item.urduName || '',
      categoryId: item.categoryId || '',
      packSize: item.packSize && item.packSize !== 'Bulk' && item.packSize !== 'Item' ? item.packSize : (item.packSize || ''),
      uomId: matchedUom?.id || item.rawRecord?.baseUomId || '',
      status: item.status || (item.isActive ? 'ACTIVE' : 'INACTIVE'),
      description: item.specifications || item.rawRecord?.description || '',
    });
    setIsProductModalOpen(true);
  };

  // Save Product Master Record (Create or Update with ZERO pricing)
  const handleSaveProduct = async () => {
    if (!productForm.name.trim()) {
      showToast({ title: 'Validation Error', message: 'Product Name is required', type: 'error' });
      return;
    }

    setIsSavingProduct(true);
    try {
      const type = productForm.itemType;

      // Parse numerical quantity and unit from packSize string (e.g. "25 KG" -> qty: 25, unit: "KG")
      let parsedQty: number | undefined;
      let parsedUnit: string | undefined;
      if (productForm.packSize) {
        const match = productForm.packSize.trim().match(/^([\d.]+)\s*(.*)$/);
        if (match && match[1]) {
          parsedQty = parseFloat(match[1]);
          parsedUnit = match[2]?.trim() || undefined;
        } else {
          parsedUnit = productForm.packSize.trim();
        }
      }

      if (type === 'FINISHED_PRODUCT') {
        const payload: any = {
          productName: productForm.name.trim(),
          urduName: productForm.urduName.trim() || undefined,
          categoryId: productForm.categoryId || undefined,
          baseUomId: productForm.uomId || undefined,
          salesUomId: productForm.uomId || undefined,
          packSizeQuantity: parsedQty,
          packSizeUnit: parsedUnit,
          packingQuantity: parsedQty,
          packingUnit: parsedUnit,
          productType: productForm.packSize || undefined,
          status: productForm.status,
        };

        if (editingItemId) {
          await ApiClient.patch(`/api/v1/master-data/finished-products/${editingItemId}`, payload);
          showToast({
            title: 'Product Updated',
            message: `[${productForm.code}] ${productForm.name} updated successfully`,
            type: 'success',
          });
        } else {
          await ApiClient.post('/api/v1/master-data/finished-products', {
            ...payload,
            productCode: 'AUTO',
          });
          showToast({
            title: 'Product Registered',
            message: `${productForm.name} added to Finished Product Master`,
            type: 'success',
          });
        }
      } else if (type === 'PACKING_MATERIAL') {
        const payload: any = {
          materialName: productForm.name.trim(),
          urduName: productForm.urduName.trim() || undefined,
          categoryId: productForm.categoryId || undefined,
          baseUomId: productForm.uomId || undefined,
          purchaseUomId: productForm.uomId || undefined,
          packCompatibility: productForm.packSize || undefined,
          description: productForm.description || undefined,
          status: productForm.status,
        };

        if (editingItemId) {
          await ApiClient.patch(`/api/v1/master-data/packing-materials/${editingItemId}`, payload);
          showToast({
            title: 'Packing Material Updated',
            message: `[${productForm.code}] ${productForm.name} updated successfully`,
            type: 'success',
          });
        } else {
          await ApiClient.post('/api/v1/master-data/packing-materials', {
            ...payload,
            materialCode: 'AUTO',
          });
          showToast({
            title: 'Packing Material Registered',
            message: `${productForm.name} added to Packing Material Master`,
            type: 'success',
          });
        }
      } else {
        // RAW_MATERIAL or OTHER
        let effectiveCategoryId = productForm.categoryId || undefined;
        if (type === 'OTHER' && !effectiveCategoryId) {
          const othCat = categories.find((c) => c.code === '41-87' || (c.name || '').toLowerCase().includes('other'));
          if (othCat) effectiveCategoryId = othCat.id;
        }

        const payload: any = {
          materialName: productForm.name.trim(),
          urduName: productForm.urduName.trim() || undefined,
          categoryId: effectiveCategoryId,
          baseUomId: productForm.uomId || undefined,
          purchaseUomId: productForm.uomId || undefined,
          specifications: productForm.packSize ? `Pack Size: ${productForm.packSize}` : productForm.description || undefined,
          status: productForm.status,
        };

        if (editingItemId) {
          await ApiClient.patch(`/api/v1/master-data/raw-materials/${editingItemId}`, payload);
          showToast({
            title: 'Item Updated',
            message: `[${productForm.code}] ${productForm.name} updated successfully`,
            type: 'success',
          });
        } else {
          await ApiClient.post('/api/v1/master-data/raw-materials', {
            ...payload,
            materialCode: 'AUTO',
          });
          showToast({
            title: 'Item Registered',
            message: `${productForm.name} added to Master Data`,
            type: 'success',
          });
        }
      }

      setIsProductModalOpen(false);
      await loadData();
    } catch (err: any) {
      showToast({ title: 'Save Failed', message: err.message || 'Error saving product item', type: 'error' });
    } finally {
      setIsSavingProduct(false);
    }
  };

  // Inline Category Creation Handler
  const handleSaveInlineCategory = async () => {
    if (!inlineCategoryForm.name.trim()) {
      showToast({ title: 'Validation Error', message: 'Category Name is required', type: 'error' });
      return;
    }

    setIsSavingCategory(true);
    try {
      const isFinished = productForm.itemType === 'FINISHED_PRODUCT';
      let createdCat: any = null;

      if (isFinished) {
        const res = await ApiClient.post('/api/v1/master-data/product-categories', {
          name: inlineCategoryForm.name.trim(),
          code: 'AUTO',
          description: inlineCategoryForm.description || undefined,
          status: 'ACTIVE',
        });
        createdCat = res.data;
      } else {
        const catType = productForm.itemType === 'PACKING_MATERIAL' ? 'PACKING_MATERIAL' : 'RAW_MATERIAL';
        const res = await ApiClient.post('/api/v1/master-data/material-categories', {
          name: inlineCategoryForm.name.trim(),
          code: 'AUTO',
          categoryType: catType,
          description: inlineCategoryForm.description || undefined,
          status: 'ACTIVE',
        });
        createdCat = res.data;
      }

      showToast({
        title: 'Category Created',
        message: `Category "${createdCat?.name || inlineCategoryForm.name}" created (Code: ${createdCat?.code || 'AUTO'})`,
        type: 'success',
      });

      // Refresh category list
      const catRes = await ApiClient.get<any[]>('/api/v1/master-data/unified-categories').catch(() =>
        ApiClient.get<any[]>('/api/v1/master-data/material-categories')
      );
      const updatedCats = catRes.data || [];
      setCategories(updatedCats);

      // Auto-select the newly created category in the active product form!
      if (createdCat?.id) {
        setProductForm((prev) => ({ ...prev, categoryId: createdCat.id }));
      } else {
        const found = updatedCats.find(
          (c: any) => c.name.toLowerCase() === inlineCategoryForm.name.trim().toLowerCase()
        );
        if (found) {
          setProductForm((prev) => ({ ...prev, categoryId: found.id }));
        }
      }

      setIsInlineCategoryModalOpen(false);
      setInlineCategoryForm({ name: '', description: '', type: 'RAW_MATERIAL' });
    } catch (err: any) {
      showToast({ title: 'Category Creation Failed', message: err.message || 'Error creating category', type: 'error' });
    } finally {
      setIsSavingCategory(false);
    }
  };

  // Inline UoM Creation Handler
  const handleSaveInlineUom = async () => {
    if (!inlineUomForm.name.trim()) {
      showToast({ title: 'Validation Error', message: 'UoM Name is required', type: 'error' });
      return;
    }

    setIsSavingUom(true);
    try {
      const res = await ApiClient.post('/api/v1/master-data/uoms', {
        name: inlineUomForm.name.trim(),
        symbol: inlineUomForm.symbol.trim() || undefined,
        code: inlineUomForm.symbol.trim() || inlineUomForm.name.trim().toUpperCase().slice(0, 6),
        category: inlineUomForm.category,
        isBaseUnit: false,
        status: 'ACTIVE',
      });
      const createdUom: any = res.data;

      showToast({
        title: 'UoM Created',
        message: `Unit of Measure "${createdUom?.name || inlineUomForm.name}" created successfully`,
        type: 'success',
      });

      // Refresh UoM list
      const uomRes = await ApiClient.get<any[]>('/api/v1/master-data/uoms');
      const updatedUoms = uomRes.data || [];
      setUoms(updatedUoms);

      // Auto-select the newly created UoM in the active product form!
      if (createdUom?.id) {
        setProductForm((prev) => ({ ...prev, uomId: createdUom.id }));
      } else {
        const found = updatedUoms.find(
          (u: any) => u.name.toLowerCase() === inlineUomForm.name.trim().toLowerCase()
        );
        if (found) {
          setProductForm((prev) => ({ ...prev, uomId: found.id }));
        }
      }

      setIsInlineUomModalOpen(false);
      setInlineUomForm({ name: '', symbol: '', category: 'WEIGHT' });
    } catch (err: any) {
      showToast({ title: 'UoM Creation Failed', message: err.message || 'Error creating unit of measure', type: 'error' });
    } finally {
      setIsSavingUom(false);
    }
  };

  // Delete Item Action
  const handleDeleteItem = async () => {
    if (!deletingItem) return;
    setIsDeleting(true);
    try {
      let endpoint = '';
      if (deletingItem.itemType === 'FINISHED_PRODUCT') {
        endpoint = `/api/v1/master-data/finished-products/${deletingItem.id}`;
      } else if (deletingItem.itemType === 'PACKING_MATERIAL') {
        endpoint = `/api/v1/master-data/packing-materials/${deletingItem.id}`;
      } else {
        endpoint = `/api/v1/master-data/raw-materials/${deletingItem.id}`;
      }

      await ApiClient.delete(endpoint);
      showToast({
        title: 'Item Deleted',
        message: `${deletingItem.name} (${deletingItem.code}) removed from catalog`,
        type: 'success',
      });
      setDeletingItem(null);
      await loadData();
    } catch (err: any) {
      showToast({ title: 'Delete Failed', message: err.message || 'Error deleting item', type: 'error' });
    } finally {
      setIsDeleting(false);
    }
  };

  // Export Catalog
  const handleExportCatalog = () => {
    const csvContent =
      'data:text/csv;charset=utf-8,' +
      ['Item Code,Product Name,Urdu Name,Type,Category,Pack Size,Base UoM,Status'].join(',') +
      '\n' +
      filteredItems
        .map(
          (i) =>
            `"${i.code}","${(i.name || '').replace(/"/g, '""')}","${(i.urduName || '').replace(/"/g, '""')}","${
              i.itemTypeLabel
            }","${(i.categoryName || '').replace(/"/g, '""')}","${i.packSize || ''}","${i.baseUomSymbol || i.baseUomName || ''}","${i.status}"`
        )
        .join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `Shehswar_Product_Master_${activeTab}_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Filter Categories by currently selected Product Type
  const relevantCategories = useMemo(() => {
    const t = productForm.itemType;
    if (t === 'FINISHED_PRODUCT') {
      return categories.filter((c) => c.entityType === 'FINISHED_PRODUCT' || c.categoryType === 'FINISHED_PRODUCT' || !c.entityType);
    } else if (t === 'PACKING_MATERIAL') {
      return categories.filter((c) => c.entityType === 'PACKING_MATERIAL' || c.categoryType === 'PACKING_MATERIAL' || !c.entityType);
    } else {
      return categories.filter((c) => c.entityType === 'RAW_MATERIAL' || c.categoryType === 'RAW_MATERIAL' || !c.entityType);
    }
  }, [categories, productForm.itemType]);

  // Common Dynamic Pack Size Suggestions
  const packSizeSuggestions = useMemo(() => {
    if (productForm.itemType === 'FINISHED_PRODUCT') {
      return ['500 ML', '1 L', '2 L', '5 L', '10 L', '20 L', '50 KG', '25 KG', '1 KG', '100 ML'];
    }
    if (productForm.itemType === 'PACKING_MATERIAL') {
      return ['PCS', 'Carton', 'Bag', 'Roll', 'Box', 'Bundle'];
    }
    return ['25 KG', '50 KG', '200 L', '1000 L', 'Bulk', '1 MT', '10 KG'];
  }, [productForm.itemType]);

  // Final Table Columns Definition — STRICTLY ZERO RATE / ZERO PRICING
  const columns = [
    {
      key: 'code',
      label: 'Item Code',
      render: (row: UnifiedProductItem) => (
        <span
          style={{
            fontFamily: 'var(--font-mono)',
            fontWeight: 700,
            fontSize: '12.5px',
            color: '#0f172a',
            padding: '3px 8px',
            borderRadius: '6px',
            backgroundColor: '#f1f5f9',
            border: '1px solid #e2e8f0',
            whiteSpace: 'nowrap',
          }}
        >
          {row.code}
        </span>
      ),
    },
    {
      key: 'name',
      label: 'Product Name',
      render: (row: UnifiedProductItem) => (
        <div style={{ maxWidth: '340px' }}>
          <div style={{ fontWeight: 700, color: '#0f172a', fontSize: '13.5px' }}>{row.name}</div>
          {row.urduName && (
            <div dir="rtl" style={{ fontSize: '12px', color: '#047857', fontWeight: 600, marginTop: '2px' }}>
              {row.urduName}
            </div>
          )}
        </div>
      ),
    },
    {
      key: 'itemType',
      label: 'Type',
      render: (row: UnifiedProductItem) => {
        let badgeStyle = {
          bg: '#ecfdf5',
          text: '#047857',
          border: '#a7f3d0',
        };
        if (row.itemType === 'RAW_MATERIAL') {
          badgeStyle = { bg: '#f0f9ff', text: '#0369a1', border: '#bae6fd' };
        } else if (row.itemType === 'PACKING_MATERIAL') {
          badgeStyle = { bg: '#f5f3ff', text: '#6d28d9', border: '#ddd6fe' };
        } else if (row.itemType === 'OTHER') {
          badgeStyle = { bg: '#f8fafc', text: '#475569', border: '#cbd5e1' };
        }

        return (
          <span
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '4px',
              padding: '3px 9px',
              borderRadius: '999px',
              fontSize: '11.5px',
              fontWeight: 700,
              backgroundColor: badgeStyle.bg,
              color: badgeStyle.text,
              border: `1px solid ${badgeStyle.border}`,
              whiteSpace: 'nowrap',
            }}
          >
            {row.itemType === 'FINISHED_PRODUCT' && '🏷️ '}
            {row.itemType === 'RAW_MATERIAL' && '💧 '}
            {row.itemType === 'PACKING_MATERIAL' && '📦 '}
            {row.itemType === 'OTHER' && '⚙️ '}
            {row.itemTypeLabel}
          </span>
        );
      },
    },
    {
      key: 'category',
      label: 'Category',
      render: (row: UnifiedProductItem) => (
        <span style={{ fontSize: '13px', color: '#334155', fontWeight: 600 }}>
          {row.categoryName}
        </span>
      ),
    },
    {
      key: 'packSize',
      label: 'Pack Size',
      render: (row: UnifiedProductItem) => (
        <span
          style={{
            display: 'inline-block',
            fontSize: '12px',
            fontWeight: 600,
            color: '#1e293b',
            backgroundColor: '#f8fafc',
            padding: '2px 8px',
            borderRadius: '5px',
            border: '1px solid #e2e8f0',
            whiteSpace: 'nowrap',
          }}
        >
          {row.packSize || '—'}
        </span>
      ),
    },
    {
      key: 'uom',
      label: 'UoM',
      render: (row: UnifiedProductItem) => (
        <span
          style={{
            fontFamily: 'var(--font-mono)',
            fontWeight: 700,
            fontSize: '11.5px',
            color: '#1e293b',
            padding: '2px 6px',
            borderRadius: '4px',
            background: '#f1f5f9',
          }}
        >
          {row.baseUomSymbol || row.baseUomName || '—'}
        </span>
      ),
    },
    {
      key: 'status',
      label: 'Status',
      render: (row: UnifiedProductItem) => (
        <StatusBadge
          status={row.isActive ? 'ACTIVE' : 'INACTIVE'}
        />
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      align: 'right' as const,
      render: (row: UnifiedProductItem) => (
        <div style={{ display: 'flex', gap: '6px', justifyContent: 'flex-end', alignItems: 'center' }}>
          {row.itemType === 'FINISHED_PRODUCT' && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => setBatchModalProduct({ id: row.id, productName: row.name })}
              title="Manage Finished Product Batches"
              style={{
                fontSize: '11px',
                height: '28px',
                padding: '0 8px',
                color: '#4f46e5',
                borderColor: '#c7d2fe',
                backgroundColor: '#eef2ff',
                fontWeight: 600,
              }}
            >
              Batches{row.batchesCount ? ` (${row.batchesCount})` : ''}
            </Button>
          )}

          <Button
            variant="ghost"
            size="sm"
            onClick={() => setViewingItem(row)}
            title="View Specifications"
            style={{ padding: '4px', height: '28px', width: '28px' }}
          >
            <IconEye size={15} />
          </Button>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => handleEditItem(row)}
            title="Edit Product Master Data"
            style={{ padding: '4px', height: '28px', width: '28px', color: '#0284c7' }}
          >
            <IconEdit size={15} />
          </Button>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => setDeletingItem(row)}
            title="Delete Record"
            style={{ padding: '4px', height: '28px', width: '28px', color: '#ef4444' }}
          >
            <IconTrash size={15} />
          </Button>
        </div>
      ),
    },
  ];

  return (
    <ListPageTemplate
      title="All Products & Items Master"
      subtitle="Central product master catalog — Identity, specifications, categories, pack sizes, and units of measure without pricing."
      actions={
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <Button variant="outline" size="sm" onClick={handleExportCatalog} icon={<IconDownload size={15} />}>
            Export
          </Button>
          <Button variant="outline" size="sm" onClick={() => setIsImportOpen(true)}>
            Import
          </Button>
          <Button variant="outline" size="sm" onClick={loadData} icon={<IconRefresh size={15} />}>
            Refresh
          </Button>
          <Button
            variant="primary"
            size="sm"
            onClick={() => handleOpenCreateModal()}
            icon={<IconPlus size={15} />}
            style={{ backgroundColor: '#0284c7', borderColor: '#0284c7' }}
          >
            + Add Product / Item
          </Button>
        </div>
      }
    >
      {/* 4 Executive KPI Metric Cards (Item Counts Only — No Pricing/Costs) */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(210px, 1fr))',
          gap: '14px',
          marginBottom: '20px',
        }}
      >
        <KpiCard
          title="Total Catalog Items"
          value={tabCounts.ALL}
          icon={<IconPackage size={20} />}
          subtitle={items.filter((i) => i.isActive).length ? `${items.filter((i) => i.isActive).length} Active` : undefined}
        />
        <KpiCard
          title="Finished Goods"
          value={tabCounts.FINISHED_PRODUCT}
          icon={<IconFlask size={20} />}
          status="success"
        />
        <KpiCard
          title="Raw Materials"
          value={tabCounts.RAW_MATERIAL}
          icon={<IconBox size={20} />}
          status="info"
        />
        <KpiCard
          title="Packing Materials"
          value={tabCounts.PACKING_MATERIAL}
          icon={<IconTag size={20} />}
          status="warning"
        />
      </div>

      {/* Main Workspace Card */}
      <Card style={{ marginBottom: '20px', overflow: 'hidden' }}>
        {/* Category Tabs Bar */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '6px',
            borderBottom: '1px solid #e2e8f0',
            backgroundColor: '#f8fafc',
            padding: '8px 16px',
            overflowX: 'auto',
          }}
        >
          {(
            [
              { id: 'ALL', label: 'All Products', count: tabCounts.ALL },
              { id: 'RAW_MATERIAL', label: 'Raw Materials', count: tabCounts.RAW_MATERIAL },
              { id: 'PACKING_MATERIAL', label: 'Packing Materials', count: tabCounts.PACKING_MATERIAL },
              { id: 'FINISHED_PRODUCT', label: 'Finished Products', count: tabCounts.FINISHED_PRODUCT },
              { id: 'OTHER', label: 'Other', count: tabCounts.OTHER },
            ] as const
          ).map((tab) => {
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setActiveTab(tab.id)}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '8px',
                  padding: '8px 16px',
                  borderRadius: '8px',
                  fontSize: '13px',
                  fontWeight: isActive ? 700 : 500,
                  color: isActive ? '#0284c7' : '#475569',
                  backgroundColor: isActive ? '#ffffff' : 'transparent',
                  border: isActive ? '1px solid #cbd5e1' : '1px solid transparent',
                  boxShadow: isActive ? '0 1px 3px rgba(0,0,0,0.06)' : 'none',
                  cursor: 'pointer',
                  transition: 'all 0.15s ease',
                  whiteSpace: 'nowrap',
                }}
              >
                <span>{tab.label}</span>
                <span
                  style={{
                    fontSize: '11px',
                    fontWeight: 700,
                    padding: '1px 7px',
                    borderRadius: '999px',
                    backgroundColor: isActive ? '#e0f2fe' : '#e2e8f0',
                    color: isActive ? '#0369a1' : '#64748b',
                  }}
                >
                  {tab.count}
                </span>
              </button>
            );
          })}
        </div>

        {/* Filter Controls Toolbar */}
        <div
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: '12px',
            padding: '16px 20px',
            backgroundColor: '#ffffff',
            borderBottom: '1px solid #f1f5f9',
            alignItems: 'center',
          }}
        >
          <div style={{ flex: '1 1 260px', minWidth: '220px' }}>
            <Input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by code, product name, category, pack size (e.g. 2L), or UoM..."
            />
          </div>

          <div style={{ width: '220px' }}>
            <Select
              value={categoryFilter}
              onChange={(val) => setCategoryFilter(typeof val === 'string' ? val : val?.target?.value || '')}
              options={[
                { value: 'ALL', label: 'All Specific Categories' },
                ...categories.map((c) => ({
                  value: c.id,
                  label: c.code ? `[${c.code}] ${c.name}` : c.name,
                })),
              ]}
            />
          </div>

          <div style={{ width: '160px' }}>
            <Select
              value={statusFilter}
              onChange={(val) => setStatusFilter(typeof val === 'string' ? val : val?.target?.value || '')}
              options={[
                { value: 'ALL', label: 'All Status' },
                { value: 'ACTIVE', label: 'Active Only' },
                { value: 'INACTIVE', label: 'Inactive Only' },
              ]}
            />
          </div>

          {(searchQuery || categoryFilter !== 'ALL' || statusFilter !== 'ALL') && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                setSearchQuery('');
                setCategoryFilter('ALL');
                setStatusFilter('ALL');
              }}
              style={{ color: '#64748b', fontSize: '12px' }}
            >
              Clear Filters
            </Button>
          )}
        </div>

        {/* DataTable Container */}
        {isLoading ? (
          <div style={{ padding: '24px' }}>
            <TableSkeleton rows={7} columns={7} />
          </div>
        ) : error ? (
          <div style={{ padding: '24px' }}>
            <ErrorState title="Failed to Load Products" message={error} onRetry={loadData} />
          </div>
        ) : filteredItems.length === 0 ? (
          <div style={{ padding: '36px 20px' }}>
            <EmptyState
              title={`No items found in ${activeTab === 'ALL' ? 'catalog' : activeTab}`}
              description={
                searchQuery
                  ? `No matching records found for "${searchQuery}". Try modifying your search or clearing filters.`
                  : 'No items registered in this category yet. Click below to add a new product or item.'
              }
              actionLabel="+ Add Product / Item"
              onAction={() => handleOpenCreateModal()}
            />
          </div>
        ) : (
          <DataTable
            columns={columns}
            data={filteredItems}
            onRowDoubleClick={(row: UnifiedProductItem) => handleEditItem(row)}
          />
        )}
      </Card>

      {/* ─────────────────────────────────────────────────────────────
          1. UNIFIED PRODUCT MASTER MODAL (ZERO PRICING / SPECIFICATIONS ONLY)
      ───────────────────────────────────────────────────────────── */}
      {isProductModalOpen && (
        <Modal
          isOpen={isProductModalOpen}
          onClose={() => setIsProductModalOpen(false)}
          title={editingItemId ? `Edit Product Master — [${productForm.code}] ${productForm.name}` : '+ Register Product / Item'}
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {/* Architectural Segregation Pill Banner */}
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '10px',
                backgroundColor: '#f0f9ff',
                border: '1px solid #bae6fd',
                padding: '10px 14px',
                borderRadius: '8px',
                fontSize: '12px',
                color: '#0369a1',
              }}
            >
              <IconPackage size={18} style={{ flexShrink: 0 }} />
              <div>
                <strong>Product Master:</strong> Defines item identity, category, pack size, and unit of measure.
                Rates belong strictly to Procurement (POs), Costing, and Rate Lists/Schemes.
              </div>
            </div>

            {/* 1. Product Type Selector */}
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '6px' }}>
                Product Type *
              </label>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '8px' }}>
                {(
                  [
                    { id: 'FINISHED_PRODUCT', label: 'Finished Product', icon: '🏷️' },
                    { id: 'RAW_MATERIAL', label: 'Raw Material', icon: '💧' },
                    { id: 'PACKING_MATERIAL', label: 'Packing Material', icon: '📦' },
                    { id: 'OTHER', label: 'Other Item', icon: '⚙️' },
                  ] as const
                ).map((t) => {
                  const isSelected = productForm.itemType === t.id;
                  return (
                    <button
                      key={t.id}
                      type="button"
                      onClick={() => {
                        setProductForm((prev) => ({
                          ...prev,
                          itemType: t.id,
                          packSize: t.id === 'FINISHED_PRODUCT' ? '1 L' : t.id === 'RAW_MATERIAL' ? '25 KG' : 'PCS',
                        }));
                      }}
                      style={{
                        padding: '10px 8px',
                        borderRadius: '8px',
                        border: `1.5px solid ${isSelected ? '#0284c7' : '#e2e8f0'}`,
                        backgroundColor: isSelected ? '#e0f2fe' : '#ffffff',
                        color: isSelected ? '#0369a1' : '#475569',
                        fontWeight: isSelected ? 700 : 500,
                        fontSize: '12px',
                        cursor: 'pointer',
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        gap: '4px',
                        transition: 'all 0.15s ease',
                      }}
                    >
                      <span style={{ fontSize: '18px' }}>{t.icon}</span>
                      <span>{t.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* 2. Product Code & Status */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Product Code
                </label>
                <div
                  style={{
                    height: '40px',
                    display: 'flex',
                    alignItems: 'center',
                    padding: '0 12px',
                    backgroundColor: '#f1f5f9',
                    border: '1.5px solid #cbd5e1',
                    borderRadius: '8px',
                    fontSize: '13px',
                    fontWeight: 700,
                    fontFamily: 'var(--font-mono)',
                    color: editingItemId ? '#0f172a' : '#0284c7',
                  }}
                >
                  {editingItemId ? productForm.code : 'AUTO (Generated upon save)'}
                </div>
                <div style={{ fontSize: '11px', color: '#64748b', marginTop: '3px' }}>
                  {productForm.itemType === 'FINISHED_PRODUCT' && 'Format: FG-XXXXXX'}
                  {productForm.itemType === 'RAW_MATERIAL' && 'Format: RM-XXXXXX'}
                  {productForm.itemType === 'PACKING_MATERIAL' && 'Format: PM-XXXXXX'}
                  {productForm.itemType === 'OTHER' && 'Format: ITEM-XXXXXX'}
                </div>
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Status
                </label>
                <Select
                  value={productForm.status}
                  onChange={(val) =>
                    setProductForm((prev) => ({
                      ...prev,
                      status: typeof val === 'string' ? val : val?.target?.value || 'ACTIVE',
                    }))
                  }
                  options={[
                    { value: 'ACTIVE', label: 'Active' },
                    { value: 'INACTIVE', label: 'Inactive' },
                  ]}
                />
              </div>
            </div>

            {/* 3. Product Name & Urdu Name */}
            <div style={{ display: 'grid', gridTemplateColumns: '3fr 2fr', gap: '12px' }}>
              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Product Name *
                </label>
                <Input
                  value={productForm.name}
                  onChange={(e) => setProductForm((prev) => ({ ...prev, name: e.target.value }))}
                  placeholder={
                    productForm.itemType === 'FINISHED_PRODUCT'
                      ? 'e.g. Chlorpyrifos 40% EC'
                      : productForm.itemType === 'PACKING_MATERIAL'
                      ? 'e.g. 2L HDPE Bottle with Cap'
                      : 'e.g. Technical Grade Solvent'
                  }
                  autoFocus
                />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Urdu Name (Optional)
                </label>
                <Input
                  value={productForm.urduName}
                  onChange={(e) => setProductForm((prev) => ({ ...prev, urduName: e.target.value }))}
                  placeholder="e.g. کلورپائریفوس"
                  dir="rtl"
                />
              </div>
            </div>

            {/* 4. Category with Inline "+ Add Category" */}
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
                <label style={{ fontSize: '12px', fontWeight: 700, color: '#334155' }}>
                  Category *
                </label>
                <button
                  type="button"
                  onClick={() => {
                    const catScope =
                      productForm.itemType === 'FINISHED_PRODUCT'
                        ? 'FINISHED_PRODUCT'
                        : productForm.itemType === 'PACKING_MATERIAL'
                        ? 'PACKING_MATERIAL'
                        : 'RAW_MATERIAL';
                    setInlineCategoryForm({ name: '', description: '', type: catScope });
                    setIsInlineCategoryModalOpen(true);
                  }}
                  style={{
                    fontSize: '11.5px',
                    fontWeight: 700,
                    color: '#0284c7',
                    background: 'none',
                    border: 'none',
                    cursor: 'pointer',
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '4px',
                    padding: '2px 4px',
                  }}
                >
                  <IconPlus size={13} /> Add Category
                </button>
              </div>

              <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                <div style={{ flex: 1 }}>
                  <Select
                    value={productForm.categoryId}
                    onChange={(val) =>
                      setProductForm((prev) => ({
                        ...prev,
                        categoryId: typeof val === 'string' ? val : val?.target?.value || '',
                      }))
                    }
                    options={relevantCategories.map((c) => ({
                      value: c.id,
                      label: c.code ? `[${c.code}] ${c.name}` : c.name,
                    }))}
                  />
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    const catScope =
                      productForm.itemType === 'FINISHED_PRODUCT'
                        ? 'FINISHED_PRODUCT'
                        : productForm.itemType === 'PACKING_MATERIAL'
                        ? 'PACKING_MATERIAL'
                        : 'RAW_MATERIAL';
                    setInlineCategoryForm({ name: '', description: '', type: catScope });
                    setIsInlineCategoryModalOpen(true);
                  }}
                  title="Add Category"
                  style={{ height: '40px', padding: '0 12px', whiteSpace: 'nowrap' }}
                >
                  <IconPlus size={14} /> Add
                </Button>
              </div>
            </div>

            {/* 5. Pack Size (Specification) & Suggestions */}
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                Pack Size (Product Specification)
              </label>
              <Input
                value={productForm.packSize}
                onChange={(e) => setProductForm((prev) => ({ ...prev, packSize: e.target.value }))}
                placeholder="e.g. 25 KG, 2 L, 1 L, 500 ML, 50 KG"
              />
              {/* Dynamic suggestion chips */}
              <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginTop: '6px' }}>
                <span style={{ fontSize: '11px', color: '#64748b', alignSelf: 'center', marginRight: '4px' }}>Suggestions:</span>
                {packSizeSuggestions.map((sug) => (
                  <button
                    key={sug}
                    type="button"
                    onClick={() => setProductForm((prev) => ({ ...prev, packSize: sug }))}
                    style={{
                      padding: '2px 8px',
                      borderRadius: '4px',
                      fontSize: '11px',
                      fontWeight: 600,
                      backgroundColor: productForm.packSize === sug ? '#0284c7' : '#f1f5f9',
                      color: productForm.packSize === sug ? '#ffffff' : '#334155',
                      border: '1px solid #cbd5e1',
                      cursor: 'pointer',
                    }}
                  >
                    {sug}
                  </button>
                ))}
              </div>
            </div>

            {/* 6. Base Unit of Measure (UoM) with Inline "+ Add UoM" */}
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
                <label style={{ fontSize: '12px', fontWeight: 700, color: '#334155' }}>
                  Base Unit of Measure (UoM) *
                </label>
                <button
                  type="button"
                  onClick={() => {
                    setInlineUomForm({
                      name: '',
                      symbol: '',
                      category: productForm.itemType === 'FINISHED_PRODUCT' ? 'VOLUME' : 'WEIGHT',
                    });
                    setIsInlineUomModalOpen(true);
                  }}
                  style={{
                    fontSize: '11.5px',
                    fontWeight: 700,
                    color: '#0284c7',
                    background: 'none',
                    border: 'none',
                    cursor: 'pointer',
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '4px',
                    padding: '2px 4px',
                  }}
                >
                  <IconPlus size={13} /> Add UoM
                </button>
              </div>

              <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                <div style={{ flex: 1 }}>
                  <Select
                    value={productForm.uomId}
                    onChange={(val) =>
                      setProductForm((prev) => ({
                        ...prev,
                        uomId: typeof val === 'string' ? val : val?.target?.value || '',
                      }))
                    }
                    options={uoms.map((u) => ({
                      value: u.id,
                      label: `${u.name} (${u.symbol || u.code})`,
                    }))}
                  />
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    setInlineUomForm({
                      name: '',
                      symbol: '',
                      category: productForm.itemType === 'FINISHED_PRODUCT' ? 'VOLUME' : 'WEIGHT',
                    });
                    setIsInlineUomModalOpen(true);
                  }}
                  title="Add UoM"
                  style={{ height: '40px', padding: '0 12px', whiteSpace: 'nowrap' }}
                >
                  <IconPlus size={14} /> Add
                </Button>
              </div>
            </div>

            {/* Form Footer */}
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '12px' }}>
              <Button variant="secondary" onClick={() => setIsProductModalOpen(false)}>
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveProduct}
                disabled={isSavingProduct}
                style={{ backgroundColor: '#0284c7', borderColor: '#0284c7' }}
              >
                {isSavingProduct ? 'Saving...' : editingItemId ? 'Update Product Item' : 'Save Product Item'}
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* ─────────────────────────────────────────────────────────────
          2. INLINE ADD CATEGORY MODAL
      ───────────────────────────────────────────────────────────── */}
      {isInlineCategoryModalOpen && (
        <Modal
          isOpen={isInlineCategoryModalOpen}
          onClose={() => setIsInlineCategoryModalOpen(false)}
          title="+ Add New Category"
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                Category Name *
              </label>
              <Input
                value={inlineCategoryForm.name}
                onChange={(e) => setInlineCategoryForm((prev) => ({ ...prev, name: e.target.value }))}
                placeholder="e.g. Insecticide, Solvent, HDPE Bottles"
                autoFocus
              />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Category Code
                </label>
                <div
                  style={{
                    height: '40px',
                    display: 'flex',
                    alignItems: 'center',
                    padding: '0 12px',
                    backgroundColor: '#f1f5f9',
                    border: '1.5px solid #cbd5e1',
                    borderRadius: '8px',
                    fontSize: '13px',
                    fontWeight: 700,
                    fontFamily: 'var(--font-mono)',
                    color: '#0284c7',
                  }}
                >
                  AUTO (Backend Generated)
                </div>
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Scope / Type
                </label>
                <Select
                  value={inlineCategoryForm.type}
                  onChange={(val) =>
                    setInlineCategoryForm((prev) => ({
                      ...prev,
                      type: typeof val === 'string' ? (val as any) : val?.target?.value || 'RAW_MATERIAL',
                    }))
                  }
                  options={[
                    { value: 'FINISHED_PRODUCT', label: 'Finished Product Category' },
                    { value: 'RAW_MATERIAL', label: 'Raw Material Category' },
                    { value: 'PACKING_MATERIAL', label: 'Packing Material Category' },
                  ]}
                />
              </div>
            </div>

            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                Description (Optional)
              </label>
              <Input
                value={inlineCategoryForm.description}
                onChange={(e) => setInlineCategoryForm((prev) => ({ ...prev, description: e.target.value }))}
                placeholder="Brief description of this category classification..."
              />
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
              <Button variant="secondary" onClick={() => setIsInlineCategoryModalOpen(false)}>
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveInlineCategory}
                disabled={isSavingCategory}
                style={{ backgroundColor: '#0284c7', borderColor: '#0284c7' }}
              >
                {isSavingCategory ? 'Creating...' : 'Create & Select Category'}
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* ─────────────────────────────────────────────────────────────
          3. INLINE ADD UOM MODAL
      ───────────────────────────────────────────────────────────── */}
      {isInlineUomModalOpen && (
        <Modal
          isOpen={isInlineUomModalOpen}
          onClose={() => setIsInlineUomModalOpen(false)}
          title="+ Add Unit of Measure (UoM)"
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                UoM Name *
              </label>
              <Input
                value={inlineUomForm.name}
                onChange={(e) => setInlineUomForm((prev) => ({ ...prev, name: e.target.value }))}
                placeholder="e.g. Liter, Kilogram, Bag, Drum, Bottle"
                autoFocus
              />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Symbol / Code *
                </label>
                <Input
                  value={inlineUomForm.symbol}
                  onChange={(e) => setInlineUomForm((prev) => ({ ...prev, symbol: e.target.value.toUpperCase() }))}
                  placeholder="e.g. LTR, KG, BAG, BTL"
                />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#334155', marginBottom: '4px' }}>
                  Measurement Dimension
                </label>
                <Select
                  value={inlineUomForm.category}
                  onChange={(val) =>
                    setInlineUomForm((prev) => ({
                      ...prev,
                      category: typeof val === 'string' ? (val as any) : val?.target?.value || 'WEIGHT',
                    }))
                  }
                  options={[
                    { value: 'WEIGHT', label: 'Weight / Mass (KG, GM, MT)' },
                    { value: 'VOLUME', label: 'Volume / Liquid (L, ML, DRUM)' },
                    { value: 'COUNT', label: 'Count / Quantity (PCS, BAG, BOX)' },
                    { value: 'LENGTH', label: 'Length (M, CM, FT)' },
                  ]}
                />
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
              <Button variant="secondary" onClick={() => setIsInlineUomModalOpen(false)}>
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveInlineUom}
                disabled={isSavingUom}
                style={{ backgroundColor: '#0284c7', borderColor: '#0284c7' }}
              >
                {isSavingUom ? 'Creating...' : 'Create & Select UoM'}
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* ─────────────────────────────────────────────────────────────
          4. VIEW ITEM DETAILS MODAL (ZERO PRICING / SPECIFICATIONS ONLY)
      ───────────────────────────────────────────────────────────── */}
      {viewingItem && (
        <Modal
          isOpen={Boolean(viewingItem)}
          onClose={() => setViewingItem(null)}
          title={`Product Master Specifications — [${viewingItem.code}] ${viewingItem.name}`}
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                gap: '14px',
                background: '#f8fafc',
                padding: '16px',
                borderRadius: '8px',
                border: '1px solid #e2e8f0',
              }}
            >
              <div>
                <div style={{ fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 600 }}>Item Code</div>
                <div style={{ fontSize: '15px', fontWeight: 800, fontFamily: 'var(--font-mono)', color: '#0f172a' }}>
                  {viewingItem.code}
                </div>
              </div>

              <div>
                <div style={{ fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 600 }}>Item Type</div>
                <div style={{ fontSize: '14px', fontWeight: 700, color: '#0284c7' }}>{viewingItem.itemTypeLabel}</div>
              </div>

              <div>
                <div style={{ fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 600 }}>Category</div>
                <div style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>{viewingItem.categoryName}</div>
              </div>

              <div>
                <div style={{ fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 600 }}>Base UOM</div>
                <div style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>
                  {viewingItem.baseUomName} ({viewingItem.baseUomSymbol || '—'})
                </div>
              </div>

              <div>
                <div style={{ fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 600 }}>Pack Size</div>
                <div style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>{viewingItem.packSize || '—'}</div>
              </div>

              <div>
                <div style={{ fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 600 }}>Status</div>
                <div style={{ marginTop: '2px' }}>
                  <StatusBadge status={viewingItem.isActive ? 'ACTIVE' : 'INACTIVE'} />
                </div>
              </div>

              {viewingItem.urduName && (
                <div style={{ gridColumn: 'span 2' }}>
                  <div style={{ fontSize: '11px', color: '#64748b', textTransform: 'uppercase', fontWeight: 600 }}>Urdu Designation</div>
                  <div dir="rtl" style={{ fontSize: '14px', fontWeight: 700, color: '#047857' }}>
                    {viewingItem.urduName}
                  </div>
                </div>
              )}
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px' }}>
              <Button
                variant="secondary"
                onClick={() => {
                  const it = viewingItem;
                  setViewingItem(null);
                  handleEditItem(it);
                }}
                icon={<IconEdit size={14} />}
              >
                Edit Item
              </Button>
              <Button variant="primary" onClick={() => setViewingItem(null)}>
                Close
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* ─────────────────────────────────────────────────────────────
          5. DELETE CONFIRMATION MODAL
      ───────────────────────────────────────────────────────────── */}
      {deletingItem && (
        <Modal
          isOpen={Boolean(deletingItem)}
          onClose={() => setDeletingItem(null)}
          title="Confirm Item Deletion"
        >
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                background: '#fef2f2',
                border: '1px solid #fecaca',
                padding: '14px',
                borderRadius: '8px',
              }}
            >
              <IconAlertTriangle size={24} style={{ color: '#dc2626', flexShrink: 0 }} />
              <div style={{ fontSize: '13px', color: '#991b1b' }}>
                Are you sure you want to delete <strong>[{deletingItem.code}] {deletingItem.name}</strong>?
                This record will be permanently marked inactive or deleted from the specialized master.
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
              <Button variant="secondary" onClick={() => setDeletingItem(null)} disabled={isDeleting}>
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleDeleteItem}
                disabled={isDeleting}
                style={{ backgroundColor: '#dc2626', borderColor: '#dc2626' }}
              >
                {isDeleting ? 'Deleting...' : 'Delete Record'}
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* ─────────────────────────────────────────────────────────────
          6. BATCH MANAGEMENT MODAL (Finished Products)
      ───────────────────────────────────────────────────────────── */}
      {batchModalProduct && (
        <AddBatchModal
          isOpen={Boolean(batchModalProduct)}
          onClose={() => setBatchModalProduct(null)}
          product={batchModalProduct}
          onBatchSaved={() => {
            loadData();
          }}
        />
      )}

      {/* ─────────────────────────────────────────────────────────────
          7. PRODUCT IMPORT MODAL
      ───────────────────────────────────────────────────────────── */}
      <ProductImportModal
        isOpen={isImportOpen}
        onClose={() => setIsImportOpen(false)}
        onImportComplete={() => {
          setIsImportOpen(false);
          loadData();
        }}
      />
    </ListPageTemplate>
  );
};
